#!/usr/bin/env python3
"""Exact certificate for the generic H7b orbit-129 force-closure exclusion.

The script reconstructs the historical exact H7b affine system, validates rational
upper secants for the sharp physical-pentagon two-gap function, checks exact Farkas
certificates for every interval bound used by the secants, and finally verifies a
strictly positive lower bound for a uniform relaxation variable. No floating point
arithmetic is used in any certificate check.
"""
from fractions import Fraction as Q
from pathlib import Path
import math

BASE = Path(__file__).with_name("verify_target_c_support7_h7b_full_angle_reduction_2026_09_19.py")
src = BASE.read_text(encoding="utf-8")
old = "vf,c=raw_force_angle(cyc,i,a,b,sd,po)"
new = "vf,c=raw_force_angle(cyc[i],i,a,b,sd,po)"
assert src.count(old) == 1
patched = src.replace(old, new)
marker = "\nCERTS={"
assert marker in patched
prefix = patched.split(marker, 1)[0]
ns = {"__name__": "_h7b_affine_base_", "__file__": str(BASE)}
exec(compile(prefix, str(BASE) + "[orbit129-base]", "exec"), ns)

reps = ns["reps"]
build_system = ns["build_system"]
X = ns["X"]
NV = ns["NV"]

EXPECTED = (
    "C7",
    ((1,2),(1,4),(2,5),(3,6),(3,7),(4,7),(5,6)),
    (1,1,5,5,4,3,2),
    (((0,1),-1),((0,2),-1),((0,3),-1),((0,4),-1),((0,5),1),((0,6),1),((0,7),-1),
     ((1,3),1),((1,5),-1),((1,6),1),((1,7),-1),((2,3),1),((2,4),1),((2,6),-1),
     ((2,7),1),((3,4),1),((3,5),-1),((4,5),1),((4,6),-1),((5,7),1),((6,7),-1)),
)
st = reps[128]
assert st == EXPECTED
base_ine, base_eq = build_system(st)
assert len(base_ine) == 112 and len(base_eq) == 92

# Machin's identity pi = 4(4 atan(1/5) - atan(1/239)). The alternating
# arctangent series supplies an exact rational enclosure for pi.
def atan_bounds(inv, n):
    x = Q(1, inv)
    s = Q(0)
    for k in range(n + 1):
        s += (-1 if k & 1 else 1) * x ** (2*k + 1) / Q(2*k + 1)
    nxt = x ** (2*n + 3) / Q(2*n + 3)
    return (s - nxt, s) if n % 2 == 0 else (s, s + nxt)

# Exact tangent check behind the branch of Machin's identity.
tan2 = Q(2,5) / (Q(1) - Q(1,25))
tan4 = (2*tan2) / (1 - tan2*tan2)
assert tan2 == Q(5,12) and tan4 == Q(120,119)
assert (tan4 - Q(1,239)) / (1 + tan4*Q(1,239)) == 1
l5,u5 = atan_bounds(5,24)
l239,u239 = atan_bounds(239,6)
PI_LO = 4*(4*l5 - u239)
PI_HI = 4*(4*u5 - l239)
assert Q(3) < PI_LO < PI_HI < Q(22,7)
assert PI_HI - PI_LO < Q(1,10**30)

def cos_lower_multiple(r, n=22):
    """Lower bound cos(r*pi), for the r values used below."""
    r = Q(r)
    assert 0 <= r <= Q(2,3)
    x = r * PI_HI
    s = Q(0)
    xx = Q(1)
    fact = 1
    for k in range(n + 1):
        if k:
            xx *= x*x
            fact *= (2*k - 1)*(2*k)
        s += (-1 if k & 1 else 1) * xx / fact
    rem = x ** (2*n + 1) / math.factorial(2*n + 1)
    return s - rem

# U(t) rationally upper-bounds the normalized sharp two-gap function
# M(t)=2[1-acos(1/2-cos(pi*t/2))/pi].
M_UPPER = {
    Q(0): Q(666667,1000000),
    Q(1,6): Q(691443,1000000),
    Q(2,9): Q(28407,40000),
    Q(1,3): Q(761437,1000000),
    Q(4,9): Q(828567,1000000),
    Q(1,2): Q(867191,1000000),
    Q(3,5): Q(944043,1000000),
    Q(2,3): Q(1),
}

def certify_m_upper(t, u):
    t,u = Q(t),Q(u)
    if t == 0:
        assert u >= Q(2,3)
        return
    if t == Q(2,3):
        assert u >= 1
        return
    q = 1 - u/Q(2)
    assert 0 < q < Q(2,3)
    # M(t)<=u is equivalent to
    # cos(q*pi)+cos(t*pi/2) >= 1/2.
    lb = cos_lower_multiple(q) + cos_lower_multiple(t/Q(2)) - Q(1,2)
    assert lb > 0

for _t,_u in M_UPPER.items():
    certify_m_upper(_t,_u)

def rcut(i,k,l,u):
    l,u = Q(l),Q(u)
    ul,uu = M_UPPER[l],M_UPPER[u]
    a = (uu-ul)/(u-l)
    b = ul-a*l
    row = {
        X[(i,(k+2)%5)]: Q(1),
        X[(i,(k+3)%5)]: Q(1),
        X[(i,k)]: -a,
    }
    return (row,b,("rational-two-gap-secant",i,k,l,u))

