def objective(**terms):
    out = [Q(0)]*NV
    for key,val in terms.items():
        i,k = map(int,key.split('_'))
        out[X[(i,k)]] = Q(val)
    return out

def verify_dual(cert, extra, c, zrelax=False):
    ine = list(base_ine) + list(extra)
    eq = list(base_eq)
    n = NV + (1 if zrelax else 0)
    assert len(c) == n
    lhs = [Q(0)]*n
    dual_obj = Q(0)
    for j,mul in cert["lam"].items():
        assert 0 <= j < len(ine) and mul <= 0
        row,rhs,_ = ine[j]
        for v,a in row.items(): lhs[v] += mul*a
        if zrelax: lhs[NV] -= mul
        dual_obj += mul*rhs
    for j,mul in cert["mu"].items():
        assert 0 <= j < len(eq)
        row,rhs,_ = eq[j]
        for v,a in row.items(): lhs[v] += mul*a
        dual_obj += mul*rhs
    assert lhs == c
    assert dual_obj == cert["obj"]
    return dual_obj

